// backend/persistence.mjs
import { AsyncLocalStorage } from "node:async_hooks";
var context = new AsyncLocalStorage();
var StoreError = class extends Error {
  constructor(message, status = 503) {
    super(message);
    this.status = status;
  }
};
function config() {
  const url = process.env.SUPABASE_URL?.replace(/\/$/, "");
  const key = process.env.SUPABASE_SECRET_KEY || process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) throw new StoreError("Ch\u01B0a c\u1EA5u h\xECnh SUPABASE_URL v\xE0 SUPABASE_SECRET_KEY tr\xEAn m\xE1y ch\u1EE7.");
  return { url, key };
}
async function cloud(path2, options = {}) {
  const { url, key } = config();
  const r = await fetch(url + path2, { ...options, signal: AbortSignal.timeout(15e3), headers: {
    apikey: key,
    ...key.startsWith("sb_secret_") ? {} : { Authorization: `Bearer ${key}` },
    "Content-Type": "application/json",
    ...options.headers
  } });
  if (!r.ok) throw new StoreError("Kh\xF4ng th\u1EC3 l\u01B0u/\u0111\u1ECDc d\u1EEF li\u1EC7u. Ki\u1EC3m tra c\u1EA5u h\xECnh Supabase v\xE0 SQL kh\u1EDFi t\u1EA1o.");
  return r;
}
async function loadSnapshot(seed) {
  let rows = await (await cloud("/rest/v1/toan10_state?id=eq.main&select=data,version")).json();
  if (!rows.length) {
    await cloud("/rest/v1/toan10_state?on_conflict=id", { method: "POST", headers: { Prefer: "resolution=ignore-duplicates" }, body: JSON.stringify({ id: "main", data: seed(), version: 0 }) });
    rows = await (await cloud("/rest/v1/toan10_state?id=eq.main&select=data,version")).json();
  }
  if (!rows[0]) throw new StoreError("Ch\u01B0a c\xF3 d\u1EEF li\u1EC7u kh\u1EDFi t\u1EA1o.");
  return rows[0];
}
async function commitSnapshot(snapshot) {
  const ok = await (await cloud("/rest/v1/rpc/toan10_save_state", { method: "POST", body: JSON.stringify({ expected_version: snapshot.version, next_data: snapshot.data }) })).json();
  if (ok !== true) throw new StoreError("C\xF3 ng\u01B0\u1EDDi kh\xE1c v\u1EEBa c\u1EADp nh\u1EADt d\u1EEF li\u1EC7u. Vui l\xF2ng th\u1EED l\u1EA1i.", 409);
}
var currentStore = new Proxy({}, {
  get(_target, key) {
    const s = context.getStore();
    if (!s) throw new Error("Missing request store");
    return s.data[key];
  },
  set(_target, key, value) {
    const s = context.getStore();
    if (!s) throw new Error("Missing request store");
    s.data[key] = value;
    return true;
  }
});
function saveStore() {
  const s = context.getStore();
  if (!s) throw new Error("Missing request store");
  s.dirty = true;
}
function storeMiddleware(seed) {
  return async (req, res, next) => {
    try {
      const snapshot = await loadSnapshot(seed);
      const state = { ...snapshot, dirty: false };
      const originalEnd = res.end.bind(res);
      let ending = false;
      res.end = function(...args) {
        if (ending) return res;
        ending = true;
        (async () => {
          try {
            if (state.dirty && res.statusCode < 400) await commitSnapshot(state);
            originalEnd(...args);
          } catch (e) {
            if (res.headersSent) {
              res.destroy(e);
              return;
            }
            res.statusCode = e.status || 503;
            res.removeHeader("Content-Length");
            res.removeHeader("ETag");
            res.setHeader("Content-Type", "application/json; charset=utf-8");
            originalEnd(JSON.stringify({ error: e.message || "Kh\xF4ng th\u1EC3 l\u01B0u d\u1EEF li\u1EC7u. Vui l\xF2ng th\u1EED l\u1EA1i." }));
          }
        })();
        return res;
      };
      context.run(state, next);
    } catch (e) {
      res.status(e.status || 503).json({ error: e.message || "Kh\xF4ng th\u1EC3 k\u1EBFt n\u1ED1i d\u1EEF li\u1EC7u." });
    }
  };
}
async function putAsset(folder, filename, buffer) {
  if (!/\.(png|jpe?g|webp|gif|svg|html)$/i.test(filename) || buffer.length > 2.5 * 1024 * 1024)
    throw new StoreError("T\u1EC7p ph\u1EA3i l\xE0 \u1EA3nh/HTML v\xE0 kh\xF4ng qu\xE1 2,5 MB.", 400);
  const mime = { png: "image/png", jpg: "image/jpeg", jpeg: "image/jpeg", webp: "image/webp", gif: "image/gif", svg: "image/svg+xml", html: "text/html" }[filename.split(".").pop().toLowerCase()];
  const bucket = process.env.SUPABASE_STORAGE_BUCKET || "toan10-media";
  const object = `${folder}/${crypto.randomUUID()}/${filename}`;
  const encoded = `${encodeURIComponent(bucket)}/${object.split("/").map(encodeURIComponent).join("/")}`;
  await cloud(`/storage/v1/object/${encoded}`, { method: "POST", headers: { "Content-Type": mime, "x-upsert": "false" }, body: buffer });
  const url = `${config().url}/storage/v1/object/public/${encoded}`;
  currentStore.assets ||= {};
  currentStore.assets[`${folder}/${filename}`] = url;
  saveStore();
  return url;
}
function assetNames(folder) {
  return Object.keys(currentStore.assets || {}).filter((k) => k.startsWith(folder + "/")).map((k) => k.slice(folder.length + 1));
}

// backend/passwords.mjs
import { randomBytes, scryptSync, timingSafeEqual } from "node:crypto";
function hashPassword(password) {
  const salt = randomBytes(16).toString("hex");
  return `scrypt:${salt}:${scryptSync(password, salt, 64).toString("hex")}`;
}
function passwordMatches(password, hash) {
  if (typeof password !== "string" || typeof hash !== "string") return false;
  const [scheme, salt, digest] = hash.split(":");
  if (scheme !== "scrypt" || !salt || !/^[a-f0-9]{128}$/.test(digest || "")) return false;
  const actual = scryptSync(password, salt, 64);
  return timingSafeEqual(actual, Buffer.from(digest, "hex"));
}

